<template>
  <main class="page-shell" v-if="orderExists">
    <router-link class="back-link" to="/orders">← Back to demo orders</router-link>
    <header class="page-heading"><div><p class="eyebrow">Demo order #{{ order?.orderId }}</p><h1>Order review</h1><p>Customer reference: {{ order?.customerId }}</p></div><div><span class="status" :class="order?.status === 0 ? 'pending' : 'completed'">{{ order?.status === 0 ? 'Needs review' : 'Completed' }}</span><button v-if="order?.status === 0" class="complete-button" type="button" @click="showConfirmation = true">Mark demo order complete</button></div></header>
    <p v-if="errorMessage" class="error-message" role="alert">{{ errorMessage }}</p>
    <section class="items-card"><div class="item-header"><span>Collection item</span><span>Quantity</span><span>Demo price</span><span>Total</span></div><div v-for="item in order?.items" :key="item.productId" class="item-row"><router-link :to="`/product/${item.productId}`"><strong>{{ productLookup(item.productId) }}</strong><small>Product {{ item.productId }}</small></router-link><span>{{ item.quantity }}</span><span>{{ formatPrice(item.price) }}</span><strong>{{ formatPrice(item.quantity * item.price) }}</strong></div><div class="summary"><span>Demo subtotal</span><strong>{{ formatPrice(calculateSubtotal()) }}</strong><span>Delivery</span><span>Not part of this demo</span><strong>Demo total</strong><strong>{{ formatPrice(calculateSubtotal()) }}</strong></div></section>
    <div v-if="showConfirmation" class="dialog-backdrop" role="presentation"><section class="confirmation" role="dialog" aria-modal="true" aria-labelledby="confirm-title"><p class="eyebrow">Confirm demo action</p><h2 id="confirm-title">Mark this order complete?</h2><p>This updates the same demo-order record used by the existing service.</p><div class="dialog-actions"><button class="secondary-button" type="button" @click="showConfirmation = false">Cancel</button><button class="complete-button" type="button" :disabled="isProcessing" @click="completeOrder">{{ isProcessing ? 'Updating…' : 'Mark complete' }}</button></div></section></div>
  </main>
  <main v-else class="empty-state"><p class="eyebrow">Order unavailable</p><h1>We could not find this demo order</h1><router-link class="button" to="/orders">Return to orders</router-link></main>
</template>

<script setup lang="ts">
import { computed, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useProductStore, useOrderStore } from '@/stores'
const productStore = useProductStore(); const orderStore = useOrderStore(); const route = useRoute(); const router = useRouter()
const showConfirmation = ref(false); const isProcessing = ref(false); const errorMessage = ref('')
const order = computed(() => orderStore.orders.find((candidate) => candidate.orderId == route.params.id))
const orderExists = computed(() => !!order.value)
const calculateSubtotal = (): number => order.value?.items.reduce((total, item) => total + item.price * item.quantity, 0) ?? 0
const productLookup = (productId: string | number): string => productStore.products.find((product) => product.id == productId)?.name ?? `Catalog item ${productId}`
const formatPrice = (price: number): string => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(price)
const completeOrder = (): void => { if (!order.value) return; const foundOrder = orderStore.orders.find((candidate) => candidate.orderId == order.value?.orderId); if (!foundOrder) return; isProcessing.value = true; errorMessage.value = ''; foundOrder.status = 1; fetch('/api/makeline/order', { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(foundOrder) }).then((response) => { if (!response.ok) throw new Error('The service did not accept the update.') }).then(() => { orderStore.removeOrder(foundOrder); router.push('/orders') }).catch(() => { foundOrder.status = 0; errorMessage.value = 'The demo order was not updated. Please try again.' }).finally(() => { isProcessing.value = false; showConfirmation.value = false }) }
</script>

<style scoped>
.page-shell, .empty-state { width: min(1180px, calc(100% - 32px)); margin: 0 auto; padding: 40px 0 72px; }.back-link { color: var(--berry); font-size: .9rem; font-weight: 800; text-decoration: none; }.page-heading { display: flex; justify-content: space-between; align-items: end; gap: 24px; margin: 26px 0 30px; }.eyebrow { margin: 0 0 7px; color: var(--berry); font-size: .75rem; font-weight: 800; letter-spacing: .12em; text-transform: uppercase; }.page-heading h1, .empty-state h1, .confirmation h2 { margin: 0; font-family: Georgia, 'Times New Roman', serif; font-weight: 500; }.page-heading h1 { font-size: clamp(2rem,4vw,3rem); }.page-heading p:not(.eyebrow), .confirmation p:not(.eyebrow) { color: var(--muted); }.page-heading > div:last-child { display: flex; align-items: center; gap: 12px; }.status { padding: 6px 9px; border-radius: 999px; font-size: .78rem; font-weight: 800; }.pending { background: #fce8cf; color: #885107; }.completed { background: #ddefda; color: #28573a; }.items-card { overflow: hidden; border: 1px solid var(--line); border-radius: var(--border-radius); background: var(--paper); box-shadow: var(--shadow); }.item-header, .item-row { display: grid; grid-template-columns: 2fr .7fr .8fr .8fr; gap: 20px; align-items: center; padding: 16px 22px; }.item-header { border-bottom: 1px solid var(--line); color: var(--muted); font-size: .72rem; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; }.item-row { border-bottom: 1px solid #eee9de; }.item-row a { color: var(--ink); text-decoration: none; }.item-row a:hover { color: var(--berry); }.item-row strong, .item-row small { display: block; }.item-row small { margin-top: 4px; color: var(--muted); }.summary { display: grid; grid-template-columns: 1fr auto; gap: 12px 32px; width: min(430px, 100%); margin-left: auto; padding: 22px; }.summary strong:nth-last-child(-n + 2) { padding-top: 12px; border-top: 1px solid var(--line); }.error-message { padding: 12px 16px; border: 1px solid #d79a92; border-radius: 8px; background: #fff0ed; color: #812c2a; }.dialog-backdrop { position: fixed; inset: 0; z-index: 20; display: grid; place-items: center; padding: 20px; background: rgba(16,42,32,.55); }.confirmation { width: min(460px,100%); padding: 28px; border-radius: 14px; background: var(--paper); box-shadow: 0 20px 55px rgba(0,0,0,.25); }.confirmation h2 { font-size: 1.8rem; }.dialog-actions { display: flex; justify-content: end; gap: 10px; margin-top: 24px; }.secondary-button { min-height: 42px; border: 1px solid var(--line); border-radius: 7px; padding: 10px 15px; background: transparent; color: var(--ink); font-weight: 800; }.complete-button:disabled { cursor: wait; opacity: .7; }.empty-state { max-width: 700px; }.empty-state .button { margin-top: 18px; }
@media (max-width: 680px) { .page-shell { padding-top: 28px; }.page-heading { align-items: start; flex-direction: column; }.item-header { display: none; }.item-row { grid-template-columns: 1fr auto; gap: 10px; padding: 16px; }.item-row > :nth-child(2) { grid-column: 1; grid-row: 2; }.item-row > :nth-child(3), .item-row > :nth-child(4) { text-align: right; }.item-row > :nth-child(4) { grid-column: 2; grid-row: 2; }.page-heading > div:last-child { align-items: start; flex-direction: column; }.summary { padding: 18px; } }
</style>
